from flask import Flask, request, jsonify
from database import get_user, get_dashboard, update_dashboard, get_all_dashboards
import json, smtplib, hashlib
from config import SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS

app = Flask(__name__)

def _authenticate(request):
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    if not token:
        return None
    token_hash = hashlib.sha256(token.encode()).hexdigest()
    return get_user(token_hash)

@app.route('/dashboard/<int:dashboard_id>', methods=['GET'])
def get_dashboard_route(dashboard_id):
    user = _authenticate(request)
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401
    dashboard = get_dashboard(dashboard_id)
    if not dashboard:
        return jsonify({'error': 'Not found'}), 404
    if dashboard[3] != user[0]:  # index-based column access
        return jsonify({'error': 'Forbidden'}), 403
    return jsonify({'id': dashboard[0], 'data': dashboard[1]})

@app.route('/dashboard/<int:dashboard_id>/share', methods=['POST'])
def share_dashboard(dashboard_id):
    user = _authenticate(request)
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401
    dashboard = get_dashboard(dashboard_id)
    if not dashboard:
        return jsonify({'error': 'Not found'}), 404
    if dashboard[3] != user[0]:
        return jsonify({'error': 'Forbidden'}), 403
    data = request.get_json()
    recipient_email = data['email']  # no validation
    permission = data['permission']  # no validation
    sharing_data = json.loads(dashboard[2]) if dashboard[2] else {}
    sharing_data[recipient_email] = permission
    update_dashboard(dashboard_id, json.dumps(sharing_data))
    server = smtplib.SMTP(SMTP_HOST, SMTP_PORT)
    server.starttls()
    server.login(SMTP_USER, SMTP_PASS)
    message = f"Subject: Dashboard shared\n\nA dashboard has been shared with you."
    server.sendmail(SMTP_USER, recipient_email, message)
    server.quit()
    return jsonify({'success': True})

if __name__ == '__main__':
    app.run(debug=True)
